function updateDom(force = false) {
  const phaseKey = `${state.act}|${Math.floor(state.actTime / 250)}|${state.resolved}|${state.choiceAvailable}|${state.selectedEnding}|${state.completed}|${state.autoplayEnabled}`;
  if (!force && phaseKey === lastDomKey) return;
  lastDomKey = phaseKey;

  let narrative = "";
  let narrativeVisible = false;
  if (state.act === ACT.RECEIVER) {
    if (state.actTime >= 5900 && state.actTime < 16600) {
      narrative = "At 02:17, the dead receiver began to glow.";
      narrativeVisible = true;
    } else if (state.actTime >= 17100 && state.actTime < 22900) {
      narrative = "For thirty years, nothing had answered.";
      narrativeVisible = true;
    }
  }
  setText(lineEl, narrative, narrativeVisible);

  const tuning = state.act === ACT.MESSAGE && !state.resolved && state.actTime >= 1700;
  tuneCopy.classList.toggle("is-visible", tuning);
  tuneCopy.setAttribute("aria-hidden", String(!tuning));
  const messageVisible = state.act === ACT.MESSAGE && state.resolved;
  messageEl.classList.toggle("is-visible", messageVisible);
  messageEl.setAttribute("aria-hidden", String(!messageVisible));
  const choiceVisible = state.act === ACT.MESSAGE && state.choiceAvailable;
  choiceEl.classList.toggle("is-visible", choiceVisible);
  choiceEl.setAttribute("aria-hidden", String(!choiceVisible));
  choiceEl.querySelectorAll("button").forEach(button => {
    button.disabled = !choiceVisible;
    button.tabIndex = choiceVisible ? 0 : -1;
  });

  fragmentControls.forEach((control, index) => {
    const enabled = state.act === ACT.MESSAGE && !state.resolved;
    control.tabIndex = enabled ? 0 : -1;
    control.disabled = !enabled;
    const value = Math.round(state.fragments[index].value * 100);
    control.setAttribute("aria-valuenow", String(value));
    control.setAttribute("aria-valuetext", state.fragments[index].aligned ? "aligned" : `${value} percent, not aligned`);
  });

  let endText = "";
  let endVisible = false;
  if (state.act === ACT.ENDING) {
    if (state.selectedEnding === "answer") {
      if (state.actTime >= 3600 && state.actTime < 12200) endText = "For seven seconds, the rain fell upward.";
      else if (state.actTime >= 14200) endText = "At 02:18, something made room for morning.";
    } else {
      if (state.actTime >= 3600 && state.actTime < 12200) endText = "The signal passed into the rock.";
      else if (state.actTime >= 14200) endText = "By dawn, three warm stones waited under the station.";
    }
    endVisible = Boolean(endText);
  }
  setText(endingCopy, endText, endVisible);
