}

function getBandLayout() {
  const portrait = height > width * 1.12;
  const center = portrait ? height * .47 : height * .51;
  const gap = portrait ? clamp(height * .085, 74, 116) : clamp(height * .12, 76, 112);
  const bandHeight = clamp(height * .085, 54, 82);
  return [0, 1, 2].map(index => ({
    top: center + (index - 1) * gap - bandHeight / 2,
    height: bandHeight,
    center: center + (index - 1) * gap
  }));
}

function layoutFragmentControls() {
  const layout = getBandLayout();
  layout.forEach((band, index) => {
    bandRects[index] = band;
    fragmentControls[index].style.top = `${band.top - 9}px`;
    fragmentControls[index].style.height = `${band.height + 18}px`;
  });

