function drawActMessage() {
  const t = state.actTime;
  const signalCoherence = coherence();
  const flash = lightningIntensity((t + 5400) % 24000) * (1 - signalCoherence * .75);
  ctx.fillStyle = flash > .1 ? "#172832" : PALETTE.storm;
  ctx.fillRect(0, 0, width, height);
  drawClouds(t + 5400, flash, signalCoherence * .2);
  drawRain(t + 5400, { signal: signalCoherence, calm: signalCoherence * .34 });

  const portrait = height > width * 1.12;
  const receiverR = Math.min(width, height) * (portrait ? .22 : .25);
  drawReceiver(width * .5, height * .51, receiverR, .35 + signalCoherence * .65, t);

  ctx.save();
  ctx.fillStyle = "rgb(2 3 4 / .78)";
  const opX = portrait ? width * .12 : width * .16;
  const opY = portrait ? height * .81 : height * .78;
  const head = Math.min(width, height) * .035;
  ctx.beginPath();
  ctx.arc(opX, opY - head * 4.1, head, 0, Math.PI * 2);
  ctx.ellipse(opX + head * .2, opY - head, head * 1.8, head * 3.6, -.08, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  if (!state.resolved) drawSignalBands(t);
  else {
    const reveal = easeOut(invLerp(state.resolvedAt, state.resolvedAt + 2100, t));
    ctx.save();
    ctx.strokeStyle = PALETTE.copper;
    ctx.globalAlpha = .22 + reveal * .46;
    ctx.lineWidth = 1;
    for (let ring = 0; ring < 3; ring += 1) {
      const radius = Math.min(width, height) * (.16 + ring * .13 + reveal * .035);
      ctx.beginPath();
