      ctx.stroke();
    }
    ctx.restore();
  }
  drawGrain(.65);
}

function drawOperator(x, ground, scale, facing = 1) {
  ctx.save();
  ctx.translate(x, ground);
  ctx.scale(facing, 1);
  ctx.fillStyle = PALETTE.black;
  ctx.beginPath();
  ctx.arc(0, -92 * scale, 14 * scale, 0, Math.PI * 2);
  ctx.moveTo(-18 * scale, -76 * scale);
  ctx.quadraticCurveTo(-26 * scale, -31 * scale, -20 * scale, 0);
  ctx.lineTo(25 * scale, 0);
  ctx.quadraticCurveTo(29 * scale, -44 * scale, 16 * scale, -76 * scale);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawAnswerEnding(time) {
  const p = easeOut(time / TIMING.ending);
  const horizon = height * .72;
  ctx.fillStyle = PALETTE.storm;
  ctx.fillRect(0, 0, width, height);
  drawClouds(time + 9000, .05, p * .15);

  const portrait = height > width * 1.12;
  const apertureX = portrait ? width * .57 : width * .64;
  const apertureY = portrait ? height * .24 : height * .29;
  const maxR = Math.min(width, height) * (portrait ? .24 : .28);
  const apertureP = smooth(invLerp(4500, 18800, time));
  if (apertureP > 0) {
    const glow = ctx.createRadialGradient(apertureX, apertureY, 0, apertureX, apertureY, maxR * 1.45);
    glow.addColorStop(0, `rgb(159 215 223 / ${.35 + apertureP * .65})`);
    glow.addColorStop(.55, `rgb(159 215 223 / ${apertureP * .34})`);
    glow.addColorStop(1, "rgb(159 215 223 / 0)");
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(apertureX, apertureY, maxR * 1.45, 0, Math.PI * 2);
    ctx.restore();
  }
  drawGrain(.55);
}

function drawSilentEnding(time) {
  const p = easeOut(time / TIMING.ending);
  const portrait = height > width * 1.12;
  const horizon = height * (portrait ? .42 : .48);
  ctx.fillStyle = "#0d171d";
  ctx.fillRect(0, 0, width, horizon);
  drawClouds(time + 11000, 0, .86 * p);
  drawRain(time + 11000, { calm: .78 * p, signal: .2 });
  ctx.fillStyle = PALETTE.earth;
  ctx.fillRect(0, horizon, width, height - horizon);

  ctx.strokeStyle = "rgb(154 169 173 / .08)";
  ctx.lineWidth = 1;
  for (let layer = 0; layer < 7; layer += 1) {
    const y = horizon + (layer + 1) * (height - horizon) / 8;
    ctx.beginPath();
    ctx.moveTo(0, y);
    for (let x = 0; x <= width; x += 44) ctx.lineTo(x, y + Math.sin(x * .014 + layer + state.seed) * 5);
    ctx.stroke();
  }

  const stationW = portrait ? width * .56 : width * .28;
  const stationH = portrait ? height * .09 : height * .14;
  const stationX = portrait ? width * .22 : width * .38;
  const stationY = horizon - stationH;
  ctx.fillStyle = PALETTE.black;
  ctx.fillRect(stationX, stationY, stationW, stationH);
