    ctx.globalAlpha = .18 + bury * .64;
    ctx.beginPath();
    const startX = stationX + stationW * .55 + strand * 4;
    const startY = horizon;
    ctx.moveTo(startX, startY);
    for (let i = 1; i <= 34; i += 1) {
      const f = i / 34;
      const x = startX + Math.sin(f * 11 + strand * 2.3) * (18 + f * 24) + strand * f * 54;
      const y = startY + f * (height - startY) * .72 * bury;
      ctx.lineTo(x, y);
      if (i > 15 && i % 8 === 0) {
        ctx.moveTo(x, y);
        ctx.lineTo(x + (strand + .2) * 22, y + 22);
        ctx.moveTo(x, y);
      }
    }
    ctx.stroke();
  }
  ctx.restore();

  const stoneY = horizon + (height - horizon) * .7;
  const stoneGap = Math.min(width, height) * .12;
  for (let index = -1; index <= 1; index += 1) {
    const stoneX = width * .5 + index * stoneGap;
    const glowP = smooth(invLerp(9300 + (index + 1) * 800, 16000 + (index + 1) * 800, time));
    const glow = ctx.createRadialGradient(stoneX, stoneY, 0, stoneX, stoneY, 42);
    glow.addColorStop(0, `rgb(240 179 95 / ${glowP * .75})`);
    glow.addColorStop(1, "rgb(197 111 61 / 0)");
